-- Productos iniciales (generado desde src/data/catalogo.mjs). Stock inicial de ejemplo: 40 unidades.
insert into public.productos (slug, nombre, categoria, precio, porciones, forma, presentacion, resumen, descripcion,
  beneficios, datos, nutricion, uso, palabras_clave, sabores, faq, visible, stock, stock_minimo, orden)
values
('whey-isolate', 'Whey Isolate', 'proteinas', 189900, 30, 'tarro', '2 lb, 30 porciones', '25 g de proteína aislada por porción, sin azúcar añadida y fácil de mezclar.', 'Proteína aislada de suero con 25 g por porción y muy poca grasa y lactosa. Se disuelve en agua o leche sin grumos y no deja sensación pesada. Ideal después de entrenar o para completar la proteína del día.', '["Ayuda a alcanzar tu meta diaria de proteína sin cocinar más.","Se mezcla en 10 segundos con agua, sin grumos.","Endulzada con stevia, sin azúcar añadida."]'::jsonb, '[{"k":"Proteína","v":"25 g","por":"por porción de 30 g"},{"k":"Azúcar añadida","v":"0 g","por":"endulzada con stevia"},{"k":"Porciones","v":"30","por":"un mes con una al día"},{"k":"Análisis","v":"Por lote","por":"laboratorio independiente"}]'::jsonb, '[["Porción","30 g"],["Energía","112 kcal"],["Proteína","25 g"],["Carbohidratos","1,2 g"],["Grasa","0,6 g"],["Sodio","60 mg"]]'::jsonb, 'Mezcla 1 scoop (30 g) con 250 ml de agua o leche. Tómalo después de entrenar o en cualquier momento del día.', array['proteína whey isolate', 'proteína aislada Colombia', 'whey sin azúcar']::text[], '[{"slug":"chocolate","nombre":"Chocolate","c1":"#6b3f2c","c2":"#2b160e"},{"slug":"vainilla","nombre":"Vainilla","c1":"#e3cb98","c2":"#9f7f46"},{"slug":"fresa","nombre":"Fresa","c1":"#d9566f","c2":"#86203f"}]'::jsonb, '[["¿Sirve si soy intolerante a la lactosa?","El aislado tiene muy poca lactosa y muchas personas con intolerancia leve lo toleran bien. Si tu intolerancia es fuerte, consulta a un profesional antes de usarlo."],["¿Cuántas porciones al día?","Una o dos, según tu meta de proteína y lo que ya comes. No reemplaza las comidas."]]'::jsonb, true, 40, 5, 0),
('creatina-monohidratada', 'Creatina Monohidratada', 'rendimiento', 99900, 60, 'tarro', '300 g, 60 porciones', 'Creatina monohidratada micronizada, 5 g por porción y un solo ingrediente.', 'Creatina monohidratada micronizada, sin sabor y sin aditivos. Es el suplemento con más estudios para fuerza y potencia en entrenamientos cortos e intensos. Una porción de 5 g al día, sin fase de carga.', '["Un solo ingrediente: creatina monohidratada.","Micronizada para que se disuelva rápido.","Sin sabor: va en agua, jugo o tu batido."]'::jsonb, '[{"k":"Creatina","v":"5 g","por":"por porción"},{"k":"Ingredientes","v":"1","por":"creatina monohidratada"},{"k":"Porciones","v":"60","por":"dos meses con una al día"},{"k":"Análisis","v":"Por lote","por":"laboratorio independiente"}]'::jsonb, '[["Porción","5 g"],["Creatina monohidratada","5 g"],["Energía","0 kcal"]]'::jsonb, 'Mezcla 5 g con agua o tu batido una vez al día, cualquier día de la semana. La constancia importa más que la hora.', array['creatina monohidratada', 'creatina micronizada Colombia', 'cómo tomar creatina']::text[], '[{"slug":"sin-sabor","nombre":"Sin sabor","c1":"#cfd4dc","c2":"#6c7380"},{"slug":"limon","nombre":"Limón","c1":"#d8e05c","c2":"#7b861f"},{"slug":"mora","nombre":"Mora","c1":"#80469a","c2":"#3a1c4d"}]'::jsonb, '[["¿Necesito fase de carga?","No es necesaria. Con 5 g al día los depósitos se llenan en unas semanas."],["¿La tomo los días que no entreno?","Sí. Tomarla todos los días mantiene los niveles estables."]]'::jsonb, true, 40, 5, 1),
('pre-entreno-pulse', 'Pre-entreno Pulse', 'rendimiento', 129900, 30, 'lata', '300 g, 30 porciones', '200 mg de cafeína, 6 g de citrulina y beta-alanina para entrenar con foco.', 'Pre-entreno con dosis declaradas: 200 mg de cafeína, 6 g de citrulina malato y 3,2 g de beta-alanina. Energía y foco sin bajón fuerte al terminar. Sin azúcar y sin colorantes artificiales.', '["Dosis completas y declaradas, sin mezclas ocultas.","200 mg de cafeína: energía sin exagerar.","Sin azúcar ni colorantes artificiales."]'::jsonb, '[{"k":"Cafeína","v":"200 mg","por":"por porción"},{"k":"Citrulina malato","v":"6 g","por":"para el bombeo"},{"k":"Beta-alanina","v":"3,2 g","por":"puede dar hormigueo leve"},{"k":"Azúcar","v":"0 g","por":"endulzado con sucralosa"}]'::jsonb, '[["Porción","10 g"],["Cafeína","200 mg"],["Citrulina malato","6 g"],["Beta-alanina","3,2 g"],["Energía","5 kcal"]]'::jsonb, 'Mezcla 1 scoop (10 g) con 300 ml de agua 20 a 30 minutos antes de entrenar. No lo tomes en las 6 horas antes de dormir.', array['pre entreno', 'pre workout Colombia', 'pre entreno con cafeína']::text[], '[{"slug":"mango","nombre":"Mango","c1":"#f29a1c","c2":"#9c5300"},{"slug":"sandia","nombre":"Sandía","c1":"#ea4f66","c2":"#851d37"},{"slug":"uva","nombre":"Uva","c1":"#7e55c9","c2":"#352072"}]'::jsonb, '[["¿Es normal el hormigueo?","Sí. Lo produce la beta-alanina, es inofensivo y pasa en unos minutos."],["¿Quién no debe tomarlo?","Menores de 18 años, personas embarazadas o sensibles a la cafeína. Si tienes una condición de salud, consulta primero."]]'::jsonb, true, 40, 5, 2),
('bcaa-2-1-1', 'BCAA 2:1:1', 'rendimiento', 109900, 40, 'lata', '280 g, 40 porciones', '7 g de aminoácidos ramificados con electrolitos para entrenar e hidratarte.', 'Aminoácidos ramificados en proporción 2:1:1 con sodio y potasio. Una bebida ligera para tomar mientras entrenas, sin azúcar y con sabores suaves.', '["7 g de BCAA en proporción 2:1:1.","Con sodio y potasio para sesiones largas.","Sabor suave, sin azúcar."]'::jsonb, '[{"k":"BCAA","v":"7 g","por":"leucina, isoleucina, valina"},{"k":"Electrolitos","v":"Na + K","por":"para sesiones largas"},{"k":"Porciones","v":"40","por":"por envase"},{"k":"Azúcar","v":"0 g","por":"endulzado con sucralosa"}]'::jsonb, '[["Porción","7 g"],["L-leucina","3,5 g"],["L-isoleucina","1,75 g"],["L-valina","1,75 g"],["Sodio","150 mg"]]'::jsonb, 'Mezcla 1 scoop en 500 ml de agua y tómalo durante el entrenamiento.', array['bcaa', 'aminoácidos ramificados', 'bcaa 2:1:1 Colombia']::text[], '[{"slug":"limonada","nombre":"Limonada","c1":"#efdc49","c2":"#97850b"},{"slug":"cereza","nombre":"Cereza","c1":"#cf3a50","c2":"#6e1226"},{"slug":"pina","nombre":"Piña","c1":"#f2b443","c2":"#9b670c"}]'::jsonb, '[["¿Necesito BCAA si tomo proteína?","Si ya cubres tu proteína diaria, el beneficio extra es pequeño. Es útil para hidratarte con sabor en sesiones largas."],["¿Lo puedo tomar en ayunas?","Sí, se tolera bien con el estómago vacío."]]'::jsonb, true, 40, 5, 3),
('barras-proteicas', 'Barras Proteicas', 'proteinas', 89900, 12, 'caja', 'Caja de 12 barras de 60 g', '20 g de proteína por barra y solo 2 g de azúcar. Para llevar en la maleta.', 'Barras con 20 g de proteína y 2 g de azúcar, con textura suave y cobertura de chocolate. Un snack para el trabajo, la universidad o después del gimnasio.', '["20 g de proteína en cada barra.","Solo 2 g de azúcar.","Empaque individual, fácil de llevar."]'::jsonb, '[{"k":"Proteína","v":"20 g","por":"por barra"},{"k":"Azúcar","v":"2 g","por":"por barra"},{"k":"Unidades","v":"12","por":"barras de 60 g"},{"k":"Fibra","v":"6 g","por":"por barra"}]'::jsonb, '[["Porción","1 barra (60 g)"],["Energía","210 kcal"],["Proteína","20 g"],["Azúcar","2 g"],["Fibra","6 g"]]'::jsonb, 'Una barra como snack entre comidas o después de entrenar.', array['barras de proteína', 'barra proteica sin azúcar', 'snack proteico']::text[], '[{"slug":"cacao","nombre":"Cacao","c1":"#5a3426","c2":"#25120a"},{"slug":"mani","nombre":"Maní","c1":"#cf9548","c2":"#784b10"},{"slug":"coco","nombre":"Coco","c1":"#e6ddcb","c2":"#a3957a"}]'::jsonb, '[["¿Contienen gluten?","Se fabrican en una planta que procesa gluten. No son aptas para personas celíacas."],["¿Cuánto duran?","Nueve meses desde la fabricación. La fecha está en cada empaque."]]'::jsonb, true, 40, 5, 4),
('shaker-halo', 'Shaker Halo 700 ml', 'accesorios', 39900, null, 'shaker', '700 ml', 'Tapa de rosca antiderrame y bolita mezcladora de acero. Va al lavavajillas.', 'Shaker de 700 ml en tritán libre de BPA, con tapa de rosca que no gotea y bolita de acero para mezclar sin grumos. Las marcas de volumen están grabadas, no se borran.', '["Tapa de rosca que no gotea en la maleta.","Bolita de acero inoxidable incluida.","Apto para lavavajillas."]'::jsonb, '[{"k":"Capacidad","v":"700 ml","por":"marcas grabadas"},{"k":"Material","v":"Tritán","por":"libre de BPA"},{"k":"Mezclador","v":"Acero","por":"inoxidable"},{"k":"Lavado","v":"Lavavajillas","por":"en la bandeja superior"}]'::jsonb, null, 'Agrega primero el líquido y luego el polvo. Cierra bien la tapa y agita 10 segundos.', array['shaker para proteína', 'shaker 700 ml', 'mezclador de proteína']::text[], '[{"slug":"grafito","nombre":"Grafito","c1":"#3b3f47","c2":"#15171b"},{"slug":"plata","nombre":"Plata","c1":"#d4d8df","c2":"#7c838f"},{"slug":"naranja","nombre":"Naranja","c1":"#ef6a2f","c2":"#8c3311"}]'::jsonb, '[["¿Guarda olor?","El tritán no absorbe olores si lo lavas el mismo día."],["¿Sirve para bebidas calientes?","No. Úsalo solo con líquidos fríos o a temperatura ambiente."]]'::jsonb, true, 40, 5, 5)
